-- Generated by gen/dump_schema.js from the Node server's migrations.
-- user_version after a fresh install: 4

CREATE TABLE access_audit_log (
      id INTEGER PRIMARY KEY AUTOINCREMENT,
      action TEXT NOT NULL,
      actor_user_id INTEGER REFERENCES users(id) ON DELETE SET NULL,
      subject_user_id INTEGER REFERENCES users(id) ON DELETE SET NULL,
      detail_json TEXT NOT NULL DEFAULT '{}',
      created_at TEXT NOT NULL DEFAULT (datetime('now'))
    );

CREATE TABLE agent_delegations (
    id TEXT PRIMARY KEY,
    user_id INTEGER NOT NULL,
    parent_agent_id TEXT NOT NULL,
    target_agent_id TEXT NOT NULL,
    parent_run_id TEXT,
    child_run_id TEXT,
    task TEXT NOT NULL,
    context TEXT,
    status TEXT DEFAULT 'pending',
    result_summary TEXT,
    error TEXT,
    created_at TEXT DEFAULT (datetime('now')),
    updated_at TEXT DEFAULT (datetime('now')),
    completed_at TEXT, mode TEXT DEFAULT 'delegate', expected_output TEXT, parent_task_id TEXT, depth INTEGER DEFAULT 0, reply_route_json TEXT, tool_restrictions_json TEXT DEFAULT '{}', allow_external_side_effects INTEGER DEFAULT 0, attempts INTEGER DEFAULT 0, awaiting_reply INTEGER DEFAULT 0, report_pending INTEGER DEFAULT 0,
    FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE CASCADE,
    FOREIGN KEY (parent_agent_id) REFERENCES agents(id) ON DELETE CASCADE,
    FOREIGN KEY (target_agent_id) REFERENCES agents(id) ON DELETE CASCADE
  );

CREATE TABLE agent_delivery_attempts (
      id TEXT PRIMARY KEY,
      outbox_id TEXT NOT NULL,
      run_id TEXT NOT NULL,
      attempt_no INTEGER NOT NULL DEFAULT 1,
      status TEXT NOT NULL
        CHECK(status IN ('started', 'delivered', 'failed', 'ambiguous')),
      platform_message_id TEXT,
      error TEXT,
      created_at TEXT DEFAULT (datetime('now')),
      FOREIGN KEY (outbox_id) REFERENCES agent_outbox(id) ON DELETE CASCADE,
      FOREIGN KEY (run_id) REFERENCES agent_runs(id) ON DELETE CASCADE
    );

CREATE TABLE agent_memory_write_queue (
      id TEXT PRIMARY KEY,
      user_id INTEGER NOT NULL,
      agent_id TEXT,
      run_id TEXT,
      candidate_json TEXT NOT NULL DEFAULT '{}',
      write_class TEXT NOT NULL DEFAULT 'semantic'
        CHECK(write_class IN ('ephemeral', 'episodic', 'semantic', 'procedural', 'discard')),
      status TEXT NOT NULL DEFAULT 'pending'
        CHECK(status IN ('pending', 'committed', 'rejected', 'failed')),
      idempotency_key TEXT,
      error TEXT,
      created_at TEXT DEFAULT (datetime('now')),
      committed_at TEXT,
      FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE CASCADE,
      FOREIGN KEY (run_id) REFERENCES agent_runs(id) ON DELETE SET NULL
    );

CREATE TABLE agent_model_usage (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    run_id TEXT NOT NULL,
    step_id TEXT,
    user_id INTEGER NOT NULL,
    agent_id TEXT,
    provider TEXT NOT NULL,
    model TEXT NOT NULL,
    phase TEXT DEFAULT 'model_turn',
    input_tokens INTEGER DEFAULT 0,
    output_tokens INTEGER DEFAULT 0,
    reasoning_tokens INTEGER DEFAULT 0,
    cached_read_tokens INTEGER DEFAULT 0,
    cache_write_tokens INTEGER DEFAULT 0,
    total_tokens INTEGER DEFAULT 0,
    estimated_cost_usd REAL,
    latency_ms INTEGER DEFAULT 0,
    metadata_json TEXT DEFAULT '{}',
    created_at TEXT DEFAULT (datetime('now')),
    FOREIGN KEY (run_id) REFERENCES agent_runs(id) ON DELETE CASCADE,
    FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE CASCADE,
    FOREIGN KEY (agent_id) REFERENCES agents(id) ON DELETE SET NULL,
    FOREIGN KEY (step_id) REFERENCES agent_steps(id) ON DELETE SET NULL
  );

CREATE TABLE agent_node_dependencies (
      run_id TEXT NOT NULL,
      node_id TEXT NOT NULL,
      depends_on_node_id TEXT NOT NULL,
      PRIMARY KEY (node_id, depends_on_node_id),
      FOREIGN KEY (run_id) REFERENCES agent_runs(id) ON DELETE CASCADE,
      FOREIGN KEY (node_id) REFERENCES agent_work_nodes(id) ON DELETE CASCADE,
      FOREIGN KEY (depends_on_node_id) REFERENCES agent_work_nodes(id) ON DELETE CASCADE
    );

CREATE TABLE agent_outbox (
      id TEXT PRIMARY KEY,
      run_id TEXT NOT NULL,
      channel TEXT NOT NULL,
      recipient TEXT,
      message_kind TEXT NOT NULL
        CHECK(message_kind IN ('ack', 'interim', 'final', 'error', 'approval', 'progress')),
      sequence INTEGER NOT NULL DEFAULT 1,
      semantic_hash TEXT,
      payload_json TEXT NOT NULL DEFAULT '{}',
      status TEXT NOT NULL DEFAULT 'pending'
        CHECK(status IN ('pending', 'leased', 'delivered', 'ambiguous', 'failed', 'suppressed')),
      platform_message_id TEXT,
      idempotency_key TEXT,
      lease_owner TEXT,
      lease_expires_at TEXT,
      created_at TEXT DEFAULT (datetime('now')),
      delivered_at TEXT, purpose TEXT, slot TEXT, scope_id TEXT,
      UNIQUE(run_id, channel, message_kind, sequence),
      FOREIGN KEY (run_id) REFERENCES agent_runs(id) ON DELETE CASCADE
    );

CREATE TABLE agent_resource_leases (
      id TEXT PRIMARY KEY,
      run_id TEXT NOT NULL,
      resource_key TEXT NOT NULL,
      mode TEXT NOT NULL DEFAULT 'exclusive'
        CHECK(mode IN ('shared_read', 'exclusive')),
      lease_owner TEXT NOT NULL,
      lease_expires_at TEXT NOT NULL,
      heartbeat_at TEXT,
      created_at TEXT DEFAULT (datetime('now')),
      UNIQUE(resource_key, mode, lease_owner),
      FOREIGN KEY (run_id) REFERENCES agent_runs(id) ON DELETE CASCADE
    );

CREATE TABLE agent_run_captures (
      id INTEGER PRIMARY KEY AUTOINCREMENT,
      run_id TEXT NOT NULL,
      user_id INTEGER NOT NULL,
      request_id TEXT NOT NULL,
      phase TEXT,
      iteration INTEGER NOT NULL DEFAULT 0,
      provider TEXT,
      model TEXT,
      reason TEXT,
      payload_json TEXT NOT NULL,
      created_at TEXT DEFAULT (datetime('now')),
      expires_at TEXT NOT NULL,
      UNIQUE(run_id, request_id),
      FOREIGN KEY (run_id) REFERENCES agent_runs(id) ON DELETE CASCADE,
      FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE CASCADE
    );

CREATE TABLE agent_run_checkpoints (
      run_id          TEXT PRIMARY KEY,
      version         INTEGER NOT NULL DEFAULT 1,
      phase           TEXT NOT NULL,
      state_json      TEXT NOT NULL DEFAULT '{}',
      created_at      TEXT DEFAULT (datetime('now')),
      updated_at      TEXT DEFAULT (datetime('now')),
      FOREIGN KEY (run_id) REFERENCES agent_runs(id) ON DELETE CASCADE
    );

CREATE TABLE agent_run_controls (
      run_id       TEXT PRIMARY KEY,
      user_id      INTEGER NOT NULL,
      action       TEXT NOT NULL CHECK(action IN ('pause', 'stop', 'interrupt')),
      reason       TEXT DEFAULT '',
      requested_at TEXT DEFAULT (datetime('now')),
      consumed_at  TEXT,
      FOREIGN KEY (run_id) REFERENCES agent_runs(id) ON DELETE CASCADE,
      FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE CASCADE
    );

CREATE TABLE agent_run_events (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    run_id TEXT NOT NULL,
    user_id INTEGER NOT NULL,
    agent_id TEXT,
    event_type TEXT NOT NULL,
    request_id TEXT,
    step_id TEXT,
    sequence_index INTEGER DEFAULT 0,
    payload_json TEXT DEFAULT '{}',
    created_at TEXT DEFAULT (datetime('now')),
    FOREIGN KEY (run_id) REFERENCES agent_runs(id) ON DELETE CASCADE,
    FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE CASCADE,
    FOREIGN KEY (agent_id) REFERENCES agents(id) ON DELETE SET NULL
  );

CREATE TABLE agent_runs (
    id TEXT PRIMARY KEY,
    user_id INTEGER NOT NULL,
    agent_id TEXT,
    title TEXT,
    status TEXT DEFAULT 'pending',
    trigger_type TEXT DEFAULT 'user',
    trigger_source TEXT,
    model TEXT,
    total_tokens INTEGER DEFAULT 0,
    prompt_metrics TEXT,
    metadata_json TEXT,
    error TEXT,
    final_response TEXT,
    created_at TEXT DEFAULT (datetime('now')),
    updated_at TEXT DEFAULT (datetime('now')),
    completed_at TEXT, conversation_id TEXT, device_target TEXT, version INTEGER NOT NULL DEFAULT 0, runtime_state TEXT NOT NULL DEFAULT 'accepted', final_delivery_id TEXT, lease_owner TEXT, lease_expires_at TEXT, heartbeat_at TEXT, metrics_json TEXT,
    FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE CASCADE,
    FOREIGN KEY (agent_id) REFERENCES agents(id) ON DELETE SET NULL
  );

CREATE TABLE agent_runtime_checkpoints (
      id TEXT PRIMARY KEY,
      run_id TEXT NOT NULL,
      version INTEGER NOT NULL DEFAULT 1,
      phase TEXT NOT NULL,
      state_json TEXT NOT NULL DEFAULT '{}',
      created_at TEXT DEFAULT (datetime('now')),
      FOREIGN KEY (run_id) REFERENCES agent_runs(id) ON DELETE CASCADE
    );

CREATE TABLE agent_settings (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    user_id INTEGER NOT NULL,
    agent_id TEXT NOT NULL,
    key TEXT NOT NULL,
    value TEXT,
    FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE CASCADE,
    FOREIGN KEY (agent_id) REFERENCES agents(id) ON DELETE CASCADE,
    UNIQUE(user_id, agent_id, key)
  );

CREATE TABLE agent_side_effects (
      id TEXT PRIMARY KEY,
      run_id TEXT NOT NULL,
      node_id TEXT,
      tool_name TEXT,
      status TEXT NOT NULL DEFAULT 'unknown'
        CHECK(status IN ('pending', 'applied', 'confirmed', 'failed', 'unknown', 'reconciled')),
      idempotency_key TEXT,
      request_json TEXT NOT NULL DEFAULT '{}',
      result_json TEXT NOT NULL DEFAULT '{}',
      created_at TEXT DEFAULT (datetime('now')),
      updated_at TEXT DEFAULT (datetime('now')),
      FOREIGN KEY (run_id) REFERENCES agent_runs(id) ON DELETE CASCADE
    );

CREATE TABLE agent_skill_evaluations (
    id TEXT PRIMARY KEY,
    skill_version_id TEXT NOT NULL,
    run_id TEXT,
    score REAL,
    outcome TEXT,
    notes TEXT,
    created_at TEXT DEFAULT (datetime('now')),
    FOREIGN KEY (skill_version_id) REFERENCES agent_skill_versions(id) ON DELETE CASCADE,
    FOREIGN KEY (run_id) REFERENCES agent_runs(id) ON DELETE SET NULL
  );

CREATE TABLE agent_skill_versions (
    id TEXT PRIMARY KEY,
    skill_id TEXT NOT NULL,
    version INTEGER NOT NULL DEFAULT 1,
    name TEXT NOT NULL,
    content_md TEXT NOT NULL DEFAULT '',
    metadata_json TEXT NOT NULL DEFAULT '{}',
    evaluation_score REAL,
    validated_at TEXT,
    status TEXT NOT NULL DEFAULT 'candidate'
      CHECK(status IN ('candidate', 'validated', 'retired', 'rolled_back')),
    created_at TEXT DEFAULT (datetime('now')),
    UNIQUE(skill_id, version)
  );

CREATE TABLE agent_steps (
    id TEXT PRIMARY KEY,
    run_id TEXT NOT NULL,
    step_index INTEGER DEFAULT 0,
    type TEXT NOT NULL,
    description TEXT,
    status TEXT DEFAULT 'pending',
    tool_name TEXT,
    tool_input TEXT,
    result TEXT,
    error TEXT,
    screenshot_path TEXT,
    tokens_used INTEGER DEFAULT 0,
    started_at TEXT,
    completed_at TEXT,
    FOREIGN KEY (run_id) REFERENCES agent_runs(id) ON DELETE CASCADE
  );

CREATE TABLE agent_task_contracts (
      id TEXT PRIMARY KEY,
      run_id TEXT NOT NULL,
      version INTEGER NOT NULL DEFAULT 1,
      contract_json TEXT NOT NULL DEFAULT '{}',
      created_at TEXT DEFAULT (datetime('now')),
      updated_at TEXT DEFAULT (datetime('now')),
      UNIQUE(run_id, version),
      FOREIGN KEY (run_id) REFERENCES agent_runs(id) ON DELETE CASCADE
    );

CREATE TABLE agent_task_messages (
      id INTEGER PRIMARY KEY AUTOINCREMENT,
      task_id TEXT NOT NULL,
      from_agent_id TEXT,
      content TEXT NOT NULL,
      delivered_at TEXT,
      created_at TEXT DEFAULT (datetime('now')),
      FOREIGN KEY (task_id) REFERENCES agent_delegations(id) ON DELETE CASCADE
    );

CREATE TABLE agent_work_nodes (
      id TEXT PRIMARY KEY,
      run_id TEXT NOT NULL,
      node_key TEXT NOT NULL,
      kind TEXT NOT NULL DEFAULT 'execute',
      status TEXT NOT NULL DEFAULT 'pending',
      version INTEGER NOT NULL DEFAULT 1,
      objective TEXT,
      success_criteria_json TEXT NOT NULL DEFAULT '[]',
      allowed_tools_json TEXT NOT NULL DEFAULT '[]',
      resource_reads_json TEXT NOT NULL DEFAULT '[]',
      resource_writes_json TEXT NOT NULL DEFAULT '[]',
      evidence_json TEXT NOT NULL DEFAULT '[]',
      artifact_ids_json TEXT NOT NULL DEFAULT '[]',
      blockers_json TEXT NOT NULL DEFAULT '[]',
      defects_json TEXT NOT NULL DEFAULT '[]',
      retry_count INTEGER NOT NULL DEFAULT 0,
      attempt_budget INTEGER NOT NULL DEFAULT 5,
      assigned_worker TEXT,
      checkpoint_id TEXT,
      metadata_json TEXT NOT NULL DEFAULT '{}',
      created_at TEXT DEFAULT (datetime('now')),
      updated_at TEXT DEFAULT (datetime('now')),
      UNIQUE(run_id, node_key),
      FOREIGN KEY (run_id) REFERENCES agent_runs(id) ON DELETE CASCADE
    );

CREATE TABLE agents (
    id TEXT PRIMARY KEY,
    user_id INTEGER NOT NULL,
    slug TEXT NOT NULL,
    display_name TEXT NOT NULL,
    description TEXT DEFAULT '',
    responsibilities TEXT DEFAULT '',
    instructions TEXT DEFAULT '',
    status TEXT DEFAULT 'active',
    is_default INTEGER DEFAULT 0,
    can_delegate INTEGER DEFAULT 0,
    can_be_delegated_to INTEGER DEFAULT 1,
    delegate_targets_json TEXT DEFAULT '[]',
    created_at TEXT DEFAULT (datetime('now')),
    updated_at TEXT DEFAULT (datetime('now')), created_by_agent_id TEXT, creation_reason TEXT, tool_restrictions_json TEXT DEFAULT '{}',
    FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE CASCADE,
    UNIQUE(user_id, slug)
  );

CREATE TABLE ai_model_health (
      user_id INTEGER NOT NULL,
      agent_id TEXT NOT NULL,
      provider_id TEXT NOT NULL,
      model_selection_id TEXT NOT NULL,
      failure_scope TEXT NOT NULL
        CHECK(failure_scope IN ('model', 'provider')),
      failure_class TEXT NOT NULL,
      failure_count INTEGER NOT NULL DEFAULT 1,
      last_status INTEGER,
      cooldown_until_ms INTEGER NOT NULL,
      created_at TEXT DEFAULT (datetime('now')),
      updated_at TEXT DEFAULT (datetime('now')),
      PRIMARY KEY (user_id, agent_id, provider_id, model_selection_id),
      FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE CASCADE
    );

CREATE TABLE approval_session_grants (
      user_id    INTEGER NOT NULL REFERENCES users(id) ON DELETE CASCADE,
      run_id     TEXT NOT NULL,
      tool_name  TEXT NOT NULL,
      expires_at TEXT NOT NULL,
      created_at TEXT DEFAULT (datetime('now')),
      updated_at TEXT DEFAULT (datetime('now')),
      PRIMARY KEY (user_id, run_id, tool_name)
    );

CREATE TABLE artifacts (
    id TEXT PRIMARY KEY,
    user_id INTEGER NOT NULL,
    kind TEXT NOT NULL,
    backend TEXT NOT NULL,
    content_type TEXT,
    storage_path TEXT NOT NULL,
    original_filename TEXT,
    byte_size INTEGER DEFAULT 0,
    metadata_json TEXT DEFAULT '{}',
    created_at TEXT DEFAULT (datetime('now')),
    FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE CASCADE
  );

CREATE TABLE assistant_self_state (
    user_id INTEGER NOT NULL,
    agent_id TEXT NOT NULL,
    identity_json TEXT DEFAULT '{}',
    focus_json TEXT DEFAULT '{}',
    updated_at TEXT DEFAULT (datetime('now')),
    PRIMARY KEY (user_id, agent_id),
    FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE CASCADE,
    FOREIGN KEY (agent_id) REFERENCES agents(id) ON DELETE CASCADE
  );

CREATE TABLE auth_oauth_states (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    user_id INTEGER,
    provider_key TEXT NOT NULL,
    mode TEXT NOT NULL,
    state TEXT NOT NULL UNIQUE,
    code_verifier TEXT NOT NULL,
    expires_at TEXT NOT NULL,
    status TEXT DEFAULT 'pending',
    result_json TEXT,
    error_message TEXT,
    created_at TEXT DEFAULT (datetime('now')),
    completed_at TEXT, signup_key TEXT,
    FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE CASCADE
  );

CREATE TABLE conversation_history (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    user_id INTEGER NOT NULL,
    agent_id TEXT,
    agent_run_id TEXT,
    role TEXT NOT NULL,
    content TEXT,
    metadata TEXT DEFAULT '{}',
    created_at TEXT DEFAULT (datetime('now')), conversation_id TEXT,
    FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE CASCADE,
    FOREIGN KEY (agent_id) REFERENCES agents(id) ON DELETE SET NULL
  );

CREATE VIRTUAL TABLE conversation_history_fts USING fts5(
      content,
      role UNINDEXED,
      user_id UNINDEXED,
      agent_id UNINDEXED,
      agent_run_id UNINDEXED,
      tokenize = 'porter unicode61'
    );

CREATE TABLE conversation_messages (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    conversation_id TEXT NOT NULL,
    role TEXT NOT NULL,
    content TEXT,
    tool_calls TEXT,
    tool_call_id TEXT,
    name TEXT,
    tokens INTEGER DEFAULT 0,
    is_compacted INTEGER DEFAULT 0,
    created_at TEXT DEFAULT (datetime('now')), run_id TEXT, agent_id TEXT, metadata_json TEXT NOT NULL DEFAULT '{}',
    FOREIGN KEY (conversation_id) REFERENCES conversations(id) ON DELETE CASCADE
  );

CREATE TABLE conversations (
    id TEXT PRIMARY KEY,
    user_id INTEGER NOT NULL,
    agent_id TEXT,
    platform TEXT DEFAULT 'web',
    platform_chat_id TEXT,
    title TEXT,
    session_key TEXT,
    model TEXT,
    total_tokens INTEGER DEFAULT 0,
    compaction_count INTEGER DEFAULT 0,
    summary TEXT,
    summary_message_count INTEGER DEFAULT 0,
    working_state_json TEXT,
    last_verified_facts_json TEXT,
    last_compaction TEXT,
    last_summary TEXT,
    created_at TEXT DEFAULT (datetime('now')),
    updated_at TEXT DEFAULT (datetime('now')),
    FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE CASCADE,
    FOREIGN KEY (agent_id) REFERENCES agents(id) ON DELETE SET NULL
  );

CREATE TABLE core_memory (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    user_id INTEGER NOT NULL,
    agent_id TEXT,
    key TEXT NOT NULL,
    value TEXT,
    updated_at TEXT DEFAULT (datetime('now')),
    UNIQUE(user_id, agent_id, key)
  );

CREATE TABLE credential_bindings (
      id TEXT PRIMARY KEY,
      user_id INTEGER NOT NULL,
      agent_id TEXT NOT NULL,
      provider_key TEXT NOT NULL,
      connection_id INTEGER NOT NULL,
      alias TEXT NOT NULL,
      usage_type TEXT NOT NULL CHECK(usage_type IN ('browser', 'http')),
      item_ref_encrypted TEXT NOT NULL,
      field_config_encrypted TEXT NOT NULL,
      target_config_json TEXT NOT NULL DEFAULT '{}',
      created_at TEXT DEFAULT (datetime('now')),
      updated_at TEXT DEFAULT (datetime('now')),
      FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE CASCADE,
      FOREIGN KEY (agent_id) REFERENCES agents(id) ON DELETE CASCADE,
      FOREIGN KEY (connection_id) REFERENCES integration_connections(id) ON DELETE CASCADE,
      UNIQUE(user_id, agent_id, alias)
    );

CREATE TABLE credential_usage_audit (
      id TEXT PRIMARY KEY,
      user_id INTEGER NOT NULL,
      agent_id TEXT NOT NULL,
      run_id TEXT,
      binding_id TEXT,
      operation TEXT NOT NULL,
      target TEXT,
      outcome TEXT NOT NULL,
      error_code TEXT,
      created_at TEXT DEFAULT (datetime('now')),
      FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE CASCADE,
      FOREIGN KEY (agent_id) REFERENCES agents(id) ON DELETE CASCADE,
      FOREIGN KEY (run_id) REFERENCES agent_runs(id) ON DELETE SET NULL,
      FOREIGN KEY (binding_id) REFERENCES credential_bindings(id) ON DELETE SET NULL
    );

CREATE TABLE delegation_invites (
      id TEXT PRIMARY KEY,
      issuer_user_id INTEGER NOT NULL REFERENCES users(id) ON DELETE CASCADE,
      token_hash TEXT NOT NULL UNIQUE,
      label TEXT NOT NULL DEFAULT '',
      permissions_json TEXT NOT NULL DEFAULT '[]',
      max_uses INTEGER CHECK (max_uses IS NULL OR max_uses > 0),
      use_count INTEGER NOT NULL DEFAULT 0,
      expires_at TEXT,
      revoked_at TEXT,
      created_at TEXT NOT NULL DEFAULT (datetime('now'))
    );

CREATE TABLE desktop_companion_devices (
    id TEXT PRIMARY KEY,
    user_id INTEGER NOT NULL,
    device_id TEXT NOT NULL,
    activation_id TEXT,
    label TEXT NOT NULL,
    hostname TEXT,
    platform TEXT,
    platform_version TEXT,
    app_version TEXT,
    companion_enabled INTEGER DEFAULT 0,
    paused INTEGER DEFAULT 0,
    status TEXT DEFAULT 'offline',
    display_count INTEGER DEFAULT 0,
    active_display_id TEXT,
    permissions_json TEXT DEFAULT '{}',
    capabilities_json TEXT DEFAULT '{}',
    metadata_json TEXT DEFAULT '{}',
    session_id INTEGER,
    last_connected_at TEXT,
    last_seen_at TEXT,
    revoked_at TEXT,
    created_at TEXT DEFAULT (datetime('now')),
    updated_at TEXT DEFAULT (datetime('now')),
    FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE CASCADE,
    UNIQUE(user_id, device_id)
  );

CREATE TABLE device_sync_commands (
      id INTEGER PRIMARY KEY AUTOINCREMENT,
      user_id INTEGER NOT NULL REFERENCES users(id) ON DELETE CASCADE,
      agent_id TEXT NOT NULL REFERENCES agents(id) ON DELETE CASCADE,
      device_id TEXT NOT NULL,
      action TEXT NOT NULL,
      payload_json TEXT NOT NULL,
      status TEXT NOT NULL DEFAULT 'pending',
      result_json TEXT,
      error TEXT,
      created_at TEXT NOT NULL DEFAULT (datetime('now')),
      completed_at TEXT
    );

CREATE TABLE device_sync_items (
      user_id INTEGER NOT NULL REFERENCES users(id) ON DELETE CASCADE,
      agent_id TEXT NOT NULL REFERENCES agents(id) ON DELETE CASCADE,
      device_id TEXT NOT NULL,
      kind TEXT NOT NULL,
      item_key TEXT NOT NULL,
      starts_at TEXT,
      ends_at TEXT,
      payload_json TEXT NOT NULL,
      PRIMARY KEY (user_id, agent_id, device_id, kind, item_key)
    );

CREATE TABLE geofences (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    user_id INTEGER NOT NULL,
    label TEXT,
    latitude REAL NOT NULL,
    longitude REAL NOT NULL,
    radius_meters INTEGER NOT NULL,
    trigger_action TEXT,
    FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE CASCADE
  );

CREATE TABLE health_metric_samples (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    user_id INTEGER NOT NULL,
    sync_run_id TEXT NOT NULL,
    metric_type TEXT NOT NULL,
    record_id TEXT NOT NULL,
    start_time TEXT,
    end_time TEXT,
    recorded_at TEXT,
    numeric_value REAL,
    text_value TEXT,
    unit TEXT,
    source_app_id TEXT,
    source_device TEXT,
    last_modified_time TEXT,
    payload_json TEXT,
    created_at TEXT DEFAULT (datetime('now')),
    updated_at TEXT DEFAULT (datetime('now')),
    FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE CASCADE,
    FOREIGN KEY (sync_run_id) REFERENCES health_sync_runs(id) ON DELETE CASCADE,
    UNIQUE(user_id, metric_type, record_id)
  );

CREATE TABLE health_sync_runs (
    id TEXT PRIMARY KEY,
    user_id INTEGER NOT NULL,
    source TEXT NOT NULL,
    provider TEXT,
    sync_window_start TEXT,
    sync_window_end TEXT,
    record_count INTEGER DEFAULT 0,
    summary_json TEXT,
    payload_json TEXT,
    created_at TEXT DEFAULT (datetime('now')),
    FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE CASCADE
  );

CREATE TABLE integration_connections (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    user_id INTEGER NOT NULL,
    agent_id TEXT,
    provider_key TEXT NOT NULL,
    app_key TEXT NOT NULL DEFAULT 'default',
    status TEXT DEFAULT 'not_connected',
    account_email TEXT,
    scopes_json TEXT DEFAULT '[]',
    credentials_json TEXT DEFAULT '{}',
    metadata_json TEXT DEFAULT '{}',
    last_connected_at TEXT,
    created_at TEXT DEFAULT (datetime('now')),
    updated_at TEXT DEFAULT (datetime('now')),
    FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE CASCADE,
    FOREIGN KEY (agent_id) REFERENCES agents(id) ON DELETE SET NULL,
    UNIQUE(user_id, agent_id, provider_key, app_key, account_email)
  );

CREATE TABLE integration_oauth_apps (
      user_id INTEGER NOT NULL REFERENCES users(id) ON DELETE CASCADE,
      provider_key TEXT NOT NULL,
      config_json TEXT NOT NULL,
      created_at TEXT NOT NULL DEFAULT (datetime('now')),
      updated_at TEXT NOT NULL DEFAULT (datetime('now')),
      PRIMARY KEY (user_id, provider_key)
    );

CREATE TABLE integration_oauth_states (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    user_id INTEGER NOT NULL,
    agent_id TEXT,
    provider_key TEXT NOT NULL,
    app_key TEXT NOT NULL DEFAULT 'default',
    state TEXT NOT NULL UNIQUE,
    code_verifier TEXT NOT NULL,
    expires_at TEXT NOT NULL,
    created_at TEXT DEFAULT (datetime('now')), memory_sweep INTEGER NOT NULL DEFAULT 0,
    FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE CASCADE,
    FOREIGN KEY (agent_id) REFERENCES agents(id) ON DELETE SET NULL
  );

CREATE TABLE integration_provider_configs (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    user_id INTEGER NOT NULL,
    agent_id TEXT,
    provider_key TEXT NOT NULL,
    config_json TEXT DEFAULT '{}',
    created_at TEXT DEFAULT (datetime('now')),
    updated_at TEXT DEFAULT (datetime('now')),
    FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE CASCADE,
    FOREIGN KEY (agent_id) REFERENCES agents(id) ON DELETE SET NULL,
    UNIQUE(user_id, agent_id, provider_key)
  );

CREATE TABLE login_failures (
      account_key TEXT NOT NULL,
      kind TEXT NOT NULL CHECK (kind IN ('password', 'second_factor')),
      failed_at_ms INTEGER NOT NULL
    );

CREATE TABLE materialized_knowledge_views (
    id TEXT PRIMARY KEY,
    user_id INTEGER NOT NULL,
    agent_id TEXT,
    view_type TEXT NOT NULL,
    subject_key TEXT NOT NULL,
    title TEXT NOT NULL,
    summary TEXT,
    markdown_text TEXT,
    source_memory_ids_json TEXT DEFAULT '[]',
    source_document_ids_json TEXT DEFAULT '[]',
    metadata_json TEXT DEFAULT '{}',
    created_at TEXT DEFAULT (datetime('now')),
    updated_at TEXT DEFAULT (datetime('now')),
    FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE CASCADE,
    FOREIGN KEY (agent_id) REFERENCES agents(id) ON DELETE SET NULL,
    UNIQUE(user_id, agent_id, view_type, subject_key)
  );

CREATE TABLE mcp_servers (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    user_id INTEGER NOT NULL,
    agent_id TEXT,
    name TEXT NOT NULL,
    command TEXT NOT NULL,
    config TEXT DEFAULT '{}',
    enabled INTEGER DEFAULT 1,
    status TEXT DEFAULT 'stopped',
    created_at TEXT DEFAULT (datetime('now')),
    FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE CASCADE,
    FOREIGN KEY (agent_id) REFERENCES agents(id) ON DELETE SET NULL
  );

CREATE TABLE memories (
    id TEXT PRIMARY KEY,
    user_id INTEGER NOT NULL,
    agent_id TEXT,
    category TEXT DEFAULT 'episodic',
    scope_type TEXT DEFAULT 'agent',
    scope_id TEXT,
    source_type TEXT,
    source_id TEXT,
    source_label TEXT,
    stale_after_days INTEGER,
    metadata_json TEXT DEFAULT '{}',
    content TEXT NOT NULL,
    importance INTEGER DEFAULT 5,
    confidence REAL DEFAULT 0.7,
    summary TEXT,
    memory_hash TEXT,
    embedding TEXT,
    access_count INTEGER DEFAULT 0,
    memory_strength REAL DEFAULT 1,
    last_accessed_at TEXT,
    pinned INTEGER DEFAULT 0,
    archived INTEGER DEFAULT 0,
    created_at TEXT DEFAULT (datetime('now')),
    updated_at TEXT DEFAULT (datetime('now')), embedding_provider TEXT, embedding_model TEXT, embedding_dimensions INTEGER, embedded_at TEXT,
    FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE CASCADE,
    FOREIGN KEY (agent_id) REFERENCES agents(id) ON DELETE SET NULL
  );

CREATE VIRTUAL TABLE memories_fts USING fts5(
      memory_id UNINDEXED,
      user_id UNINDEXED,
      agent_id UNINDEXED,
      content,
      category,
      entities,
      tokenize = 'porter unicode61'
    );

CREATE TABLE memory_embedding_bands (
      memory_id TEXT NOT NULL,
      user_id INTEGER NOT NULL,
      agent_id TEXT NOT NULL,
      dimension INTEGER NOT NULL,
      index_version INTEGER NOT NULL DEFAULT 3,
      band_index INTEGER NOT NULL,
      band_value INTEGER NOT NULL,
      updated_at TEXT DEFAULT (datetime('now')),
      PRIMARY KEY (memory_id, band_index),
      FOREIGN KEY (memory_id) REFERENCES memories(id) ON DELETE CASCADE,
      FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE CASCADE
    );

CREATE TABLE memory_entities (
    id TEXT PRIMARY KEY,
    user_id INTEGER NOT NULL,
    agent_id TEXT,
    entity_key TEXT NOT NULL,
    name TEXT NOT NULL,
    kind TEXT DEFAULT 'concept',
    aliases_json TEXT DEFAULT '[]',
    summary TEXT DEFAULT '',
    mention_count INTEGER DEFAULT 0,
    first_seen_at TEXT DEFAULT (datetime('now')),
    last_seen_at TEXT DEFAULT (datetime('now')),
    metadata_json TEXT DEFAULT '{}',
    UNIQUE(user_id, agent_id, entity_key),
    FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE CASCADE,
    FOREIGN KEY (agent_id) REFERENCES agents(id) ON DELETE SET NULL
  );

CREATE TABLE memory_entity_mentions (
    entity_id TEXT NOT NULL,
    memory_id TEXT NOT NULL,
    user_id INTEGER NOT NULL,
    agent_id TEXT,
    created_at TEXT DEFAULT (datetime('now')), in_sentence INTEGER,
    PRIMARY KEY (entity_id, memory_id),
    FOREIGN KEY (entity_id) REFERENCES memory_entities(id) ON DELETE CASCADE,
    FOREIGN KEY (memory_id) REFERENCES memories(id) ON DELETE CASCADE,
    FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE CASCADE,
    FOREIGN KEY (agent_id) REFERENCES agents(id) ON DELETE SET NULL
  );

CREATE TABLE memory_facts (
    id TEXT PRIMARY KEY,
    memory_id TEXT NOT NULL,
    user_id INTEGER NOT NULL,
    agent_id TEXT,
    subject TEXT NOT NULL,
    predicate TEXT NOT NULL,
    object TEXT NOT NULL,
    category TEXT DEFAULT 'episodic',
    confidence REAL DEFAULT 0.7,
    event_time TEXT,
    metadata_json TEXT DEFAULT '{}',
    created_at TEXT DEFAULT (datetime('now')),
    updated_at TEXT DEFAULT (datetime('now')), valid_from TEXT, valid_to TEXT, learned_at TEXT, invalidated_at TEXT, status TEXT DEFAULT 'active', supersedes_fact_id TEXT,
    FOREIGN KEY (memory_id) REFERENCES memories(id) ON DELETE CASCADE,
    FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE CASCADE,
    FOREIGN KEY (agent_id) REFERENCES agents(id) ON DELETE SET NULL
  );

CREATE TABLE memory_ingestion_documents (
    id TEXT PRIMARY KEY,
    user_id INTEGER NOT NULL,
    agent_id TEXT,
    source_type TEXT NOT NULL,
    normalized_type TEXT NOT NULL,
    provider_key TEXT DEFAULT '',
    connection_id INTEGER NOT NULL DEFAULT 0,
    external_object_id TEXT NOT NULL,
    source_account TEXT,
    title TEXT,
    content TEXT NOT NULL,
    summary TEXT,
    salience INTEGER DEFAULT 5,
    source_timestamp TEXT,
    metadata_json TEXT DEFAULT '{}',
    payload_json TEXT DEFAULT '{}',
    created_at TEXT DEFAULT (datetime('now')),
    updated_at TEXT DEFAULT (datetime('now')),
    FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE CASCADE,
    FOREIGN KEY (agent_id) REFERENCES agents(id) ON DELETE SET NULL,
    UNIQUE(user_id, agent_id, source_type, provider_key, connection_id, external_object_id)
  );

CREATE TABLE memory_ingestion_jobs (
    id TEXT PRIMARY KEY,
    user_id INTEGER NOT NULL,
    agent_id TEXT,
    source_type TEXT NOT NULL,
    provider_key TEXT DEFAULT '',
    connection_id INTEGER,
    status TEXT DEFAULT 'pending',
    freshness_policy_json TEXT DEFAULT '{}',
    cursor_json TEXT DEFAULT '{}',
    summary_json TEXT DEFAULT '{}',
    metadata_json TEXT DEFAULT '{}',
    document_count INTEGER DEFAULT 0,
    error_text TEXT,
    started_at TEXT DEFAULT (datetime('now')),
    completed_at TEXT,
    next_sync_at TEXT,
    created_at TEXT DEFAULT (datetime('now')),
    updated_at TEXT DEFAULT (datetime('now')),
    FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE CASCADE,
    FOREIGN KEY (agent_id) REFERENCES agents(id) ON DELETE SET NULL,
    FOREIGN KEY (connection_id) REFERENCES integration_connections(id) ON DELETE SET NULL
  );

CREATE TABLE memory_relations (
      id TEXT PRIMARY KEY,
      user_id INTEGER NOT NULL,
      agent_id TEXT,
      from_memory_id TEXT NOT NULL,
      to_memory_id TEXT NOT NULL,
      relation_type TEXT NOT NULL CHECK(relation_type IN ('updates', 'extends', 'derives')),
      confidence REAL DEFAULT 0.7,
      metadata_json TEXT DEFAULT '{}',
      created_at TEXT DEFAULT (datetime('now')),
      UNIQUE(from_memory_id, to_memory_id, relation_type),
      FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE CASCADE,
      FOREIGN KEY (agent_id) REFERENCES agents(id) ON DELETE SET NULL,
      FOREIGN KEY (from_memory_id) REFERENCES memories(id) ON DELETE CASCADE,
      FOREIGN KEY (to_memory_id) REFERENCES memories(id) ON DELETE CASCADE
    );

CREATE TABLE memory_retrieval_events (
      id INTEGER PRIMARY KEY AUTOINCREMENT,
      user_id INTEGER NOT NULL,
      agent_id TEXT NOT NULL,
      query_hash TEXT NOT NULL,
      scope_type TEXT NOT NULL,
      scope_id TEXT,
      requested_k INTEGER NOT NULL,
      candidate_count INTEGER DEFAULT 0,
      semantic_candidate_count INTEGER DEFAULT 0,
      lexical_candidate_count INTEGER DEFAULT 0,
      entity_candidate_count INTEGER DEFAULT 0,
      relation_candidate_count INTEGER DEFAULT 0,
      result_count INTEGER DEFAULT 0,
      result_ids_json TEXT DEFAULT '[]',
      context_tokens_estimate INTEGER DEFAULT 0,
      latency_ms REAL DEFAULT 0,
      created_at TEXT DEFAULT (datetime('now')),
      FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE CASCADE
    );

CREATE TABLE memory_source_chunks (
      id TEXT PRIMARY KEY,
      document_id TEXT NOT NULL,
      user_id INTEGER NOT NULL,
      agent_id TEXT NOT NULL,
      chunk_index INTEGER NOT NULL,
      char_start INTEGER NOT NULL,
      char_end INTEGER NOT NULL,
      content TEXT NOT NULL,
      content_hash TEXT NOT NULL,
      metadata_json TEXT DEFAULT '{}',
      created_at TEXT DEFAULT (datetime('now')),
      updated_at TEXT DEFAULT (datetime('now')),
      FOREIGN KEY (document_id) REFERENCES memory_ingestion_documents(id) ON DELETE CASCADE,
      FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE CASCADE,
      UNIQUE(document_id, content_hash)
    );

CREATE TABLE memory_source_links (
      memory_id TEXT NOT NULL,
      chunk_id TEXT NOT NULL,
      source_document_id TEXT NOT NULL,
      source_timestamp TEXT,
      relevance_score REAL DEFAULT 1,
      extraction_method TEXT DEFAULT 'source_chunk',
      metadata_json TEXT DEFAULT '{}',
      created_at TEXT DEFAULT (datetime('now')),
      PRIMARY KEY (memory_id, chunk_id),
      FOREIGN KEY (memory_id) REFERENCES memories(id) ON DELETE CASCADE,
      FOREIGN KEY (chunk_id) REFERENCES memory_source_chunks(id) ON DELETE CASCADE,
      FOREIGN KEY (source_document_id) REFERENCES memory_ingestion_documents(id) ON DELETE CASCADE
    );

CREATE TABLE messages (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    user_id INTEGER NOT NULL,
    agent_id TEXT,
    run_id TEXT,
    role TEXT NOT NULL,
    content TEXT,
    tool_calls TEXT,
    tool_call_id TEXT,
    platform TEXT DEFAULT 'web',
    platform_msg_id TEXT,
    platform_chat_id TEXT,
    media_path TEXT,
    metadata TEXT,
    created_at TEXT DEFAULT (datetime('now')),
    FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE CASCADE,
    FOREIGN KEY (agent_id) REFERENCES agents(id) ON DELETE SET NULL
  );

CREATE VIRTUAL TABLE messages_fts USING fts5(
      content,
      role UNINDEXED,
      user_id UNINDEXED,
      agent_id UNINDEXED,
      run_id UNINDEXED,
      platform UNINDEXED,
      platform_chat_id UNINDEXED,
      tokenize = 'porter unicode61'
    );

CREATE TABLE messaging_identity_links (
      id            INTEGER PRIMARY KEY AUTOINCREMENT,
      platform      TEXT NOT NULL,
      external_id   TEXT NOT NULL,
      chat_id       TEXT NOT NULL,
      display_name  TEXT,
      user_id       INTEGER NOT NULL,
      agent_id      TEXT NOT NULL,
      linked_at     TEXT NOT NULL DEFAULT (datetime('now')),
      FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE CASCADE,
      FOREIGN KEY (agent_id) REFERENCES agents(id) ON DELETE CASCADE,
      UNIQUE(platform, external_id),
      UNIQUE(platform, user_id)
    );

CREATE TABLE messaging_inbound_jobs (
      id                TEXT PRIMARY KEY,
      message_id        INTEGER NOT NULL UNIQUE,
      user_id           INTEGER NOT NULL,
      agent_id          TEXT,
      platform          TEXT NOT NULL,
      platform_msg_id   TEXT,
      platform_chat_id  TEXT,
      payload_json      TEXT NOT NULL,
      status            TEXT NOT NULL DEFAULT 'pending'
                        CHECK(status IN ('pending', 'processing', 'completed', 'failed')),
      attempts          INTEGER NOT NULL DEFAULT 0,
      run_id            TEXT,
      last_error        TEXT,
      created_at        TEXT NOT NULL DEFAULT (datetime('now')),
      updated_at        TEXT NOT NULL DEFAULT (datetime('now')),
      completed_at      TEXT,
      FOREIGN KEY (message_id) REFERENCES messages(id) ON DELETE CASCADE,
      FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE CASCADE,
      FOREIGN KEY (agent_id) REFERENCES agents(id) ON DELETE SET NULL
    );

CREATE TABLE messaging_link_codes (
      code_hash   TEXT PRIMARY KEY,
      platform    TEXT NOT NULL,
      user_id     INTEGER NOT NULL,
      agent_id    TEXT NOT NULL,
      expires_at  INTEGER NOT NULL,
      FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE CASCADE,
      FOREIGN KEY (agent_id) REFERENCES agents(id) ON DELETE CASCADE,
      UNIQUE(platform, user_id)
    );

CREATE TABLE messaging_shared_connections (
      platform        TEXT PRIMARY KEY,
      config          TEXT NOT NULL DEFAULT '',
      enabled         INTEGER NOT NULL DEFAULT 1,
      available       INTEGER NOT NULL DEFAULT 1,
      allow_personal  INTEGER NOT NULL DEFAULT 1,
      revision        INTEGER NOT NULL DEFAULT 1,
      status          TEXT NOT NULL DEFAULT 'connecting',
      status_reason   TEXT,
      account_id      TEXT,
      account_label   TEXT,
      qr              TEXT,
      last_connected  TEXT,
      updated_at      TEXT NOT NULL DEFAULT (datetime('now'))
    );

CREATE TABLE neoagent_instance (
      singleton_id INTEGER PRIMARY KEY CHECK(singleton_id = 1),
      instance_id TEXT NOT NULL UNIQUE,
      display_name TEXT NOT NULL,
      created_at TEXT NOT NULL DEFAULT (datetime('now')),
      updated_at TEXT NOT NULL DEFAULT (datetime('now'))
    );

CREATE TABLE notification_history (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    user_id INTEGER NOT NULL,
    app_package TEXT,
    title TEXT,
    body TEXT,
    timestamp TEXT DEFAULT (datetime('now')),
    action_taken TEXT,
    FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE CASCADE
  );

CREATE TABLE pending_approvals (
      id             TEXT PRIMARY KEY,
      user_id        INTEGER NOT NULL REFERENCES users(id) ON DELETE CASCADE,
      run_id         TEXT REFERENCES agent_runs(id) ON DELETE CASCADE,
      tool_name      TEXT NOT NULL,
      tool_args_json TEXT,
      category       TEXT,
      status         TEXT NOT NULL CHECK(status IN ('pending','approved','denied','timeout','expired')),
      scope          TEXT CHECK(scope IN ('once','session','always')),
      expires_at     TEXT NOT NULL,
      decided_at     TEXT,
      created_at     TEXT DEFAULT (datetime('now')),
      updated_at     TEXT DEFAULT (datetime('now'))
    );

CREATE TABLE platform_connections (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    user_id INTEGER NOT NULL,
    agent_id TEXT,
    platform TEXT NOT NULL,
    config TEXT DEFAULT '{}',
    status TEXT DEFAULT 'disconnected',
    auth_data_path TEXT,
    last_connected TEXT,
    created_at TEXT DEFAULT (datetime('now')),
    FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE CASCADE,
    FOREIGN KEY (agent_id) REFERENCES agents(id) ON DELETE SET NULL,
    UNIQUE(user_id, agent_id, platform)
  );

CREATE TABLE scheduled_tasks (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    user_id INTEGER NOT NULL,
    agent_id TEXT,
    name TEXT NOT NULL,
    trigger_type TEXT DEFAULT 'schedule',
    trigger_config TEXT DEFAULT '{}',
    cron_expression TEXT,
    run_at TEXT,
    one_time INTEGER DEFAULT 0,
    execution_mode TEXT DEFAULT 'prompt',
    task_type TEXT DEFAULT 'agent_prompt',
    task_config TEXT DEFAULT '{}',
    enabled INTEGER DEFAULT 1,
    last_run TEXT,
    last_triggered_at TEXT,
    last_trigger_fingerprint TEXT,
    created_at TEXT DEFAULT (datetime('now')),
    FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE CASCADE,
    FOREIGN KEY (agent_id) REFERENCES agents(id) ON DELETE SET NULL
  );

CREATE TABLE setup_claim_tokens (
      id TEXT PRIMARY KEY,
      token_hash TEXT NOT NULL UNIQUE,
      expires_at TEXT NOT NULL,
      exchanged_at TEXT,
      consumed_at TEXT,
      created_at TEXT NOT NULL DEFAULT (datetime('now'))
    );

CREATE TABLE signup_keys (
      id INTEGER PRIMARY KEY AUTOINCREMENT,
      code TEXT NOT NULL UNIQUE,
      label TEXT NOT NULL DEFAULT '',
      created_by_user_id INTEGER REFERENCES users(id) ON DELETE SET NULL,
      created_at TEXT NOT NULL DEFAULT (datetime('now')),
      used_at TEXT,
      used_by_user_id INTEGER REFERENCES users(id) ON DELETE SET NULL,
      revoked_at TEXT
    );

CREATE TABLE skill_learning_candidates (
      id TEXT PRIMARY KEY,
      user_id INTEGER NOT NULL,
      workflow_key TEXT NOT NULL,
      title TEXT NOT NULL,
      summary TEXT NOT NULL DEFAULT '',
      observation_count INTEGER NOT NULL DEFAULT 1,
      latest_run_id TEXT,
      evidence_json TEXT NOT NULL DEFAULT '[]',
      status TEXT NOT NULL DEFAULT 'observing'
        CHECK(status IN ('observing', 'promoted', 'dismissed')),
      skill_name TEXT,
      created_at TEXT NOT NULL DEFAULT (datetime('now')),
      updated_at TEXT NOT NULL DEFAULT (datetime('now')),
      UNIQUE(user_id, workflow_key),
      FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE CASCADE,
      FOREIGN KEY (latest_run_id) REFERENCES agent_runs(id) ON DELETE SET NULL
    );

CREATE TABLE skill_learning_state (
      user_id INTEGER NOT NULL,
      agent_scope TEXT NOT NULL DEFAULT '',
      activity_score INTEGER NOT NULL DEFAULT 0,
      updated_at TEXT NOT NULL DEFAULT (datetime('now')),
      PRIMARY KEY (user_id, agent_scope),
      FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE CASCADE
    );

CREATE TABLE skill_metrics (
    user_id INTEGER NOT NULL,
    agent_id TEXT,
    skill_name TEXT NOT NULL,
    invocation_count INTEGER DEFAULT 0,
    success_count INTEGER DEFAULT 0,
    failure_count INTEGER DEFAULT 0,
    correction_count INTEGER DEFAULT 0,
    total_tokens INTEGER DEFAULT 0,
    last_used_at TEXT,
    metadata_json TEXT DEFAULT '{}',
    updated_at TEXT DEFAULT (datetime('now')),
    PRIMARY KEY (user_id, agent_id, skill_name),
    FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE CASCADE,
    FOREIGN KEY (agent_id) REFERENCES agents(id) ON DELETE SET NULL
  );

CREATE TABLE skills (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    user_id INTEGER NOT NULL DEFAULT 0,
    name TEXT NOT NULL,
    description TEXT,
    file_path TEXT NOT NULL,
    metadata TEXT DEFAULT '{}',
    enabled INTEGER DEFAULT 1,
    auto_created INTEGER DEFAULT 0,
    created_at TEXT DEFAULT (datetime('now')),
    updated_at TEXT DEFAULT (datetime('now'))
  );

CREATE TABLE task_webhook_deliveries (
    id TEXT PRIMARY KEY,
    task_id INTEGER NOT NULL,
    user_id INTEGER NOT NULL,
    request_id TEXT NOT NULL,
    payload_hash TEXT NOT NULL,
    status TEXT NOT NULL DEFAULT 'accepted',
    response_json TEXT DEFAULT '{}',
    created_at TEXT DEFAULT (datetime('now')),
    completed_at TEXT,
    FOREIGN KEY (task_id) REFERENCES scheduled_tasks(id) ON DELETE CASCADE,
    FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE CASCADE,
    UNIQUE(task_id, request_id)
  );

CREATE TABLE task_webhook_secrets (
    task_id INTEGER PRIMARY KEY,
    user_id INTEGER NOT NULL,
    secret_encrypted TEXT NOT NULL,
    secret_fingerprint TEXT NOT NULL,
    rotated_at TEXT DEFAULT (datetime('now')),
    created_at TEXT DEFAULT (datetime('now')),
    FOREIGN KEY (task_id) REFERENCES scheduled_tasks(id) ON DELETE CASCADE,
    FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE CASCADE
  );

CREATE TABLE timeline_events (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    user_id INTEGER NOT NULL,
    agent_id TEXT,
    source_kind TEXT NOT NULL,
    event_kind TEXT NOT NULL,
    occurred_at TEXT NOT NULL,
    title TEXT NOT NULL,
    summary TEXT,
    source_id TEXT,
    group_key TEXT,
    metadata_json TEXT DEFAULT '{}',
    created_at TEXT DEFAULT (datetime('now')),
    FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE CASCADE,
    FOREIGN KEY (agent_id) REFERENCES agents(id) ON DELETE SET NULL
  );

CREATE TABLE tool_approval_log (
      id             TEXT    PRIMARY KEY,
      user_id        INTEGER NOT NULL REFERENCES users(id) ON DELETE CASCADE,
      run_id         TEXT    NOT NULL,
      tool_name      TEXT    NOT NULL,
      tool_args_json TEXT,
      decision       TEXT    NOT NULL CHECK(decision IN ('approved','denied','timeout')),
      scope          TEXT    NOT NULL CHECK(scope IN ('once','session','always')),
      decided_at     TEXT    DEFAULT (datetime('now'))
    );

CREATE TABLE tool_policies (
      user_id    INTEGER NOT NULL REFERENCES users(id) ON DELETE CASCADE,
      category   TEXT    NOT NULL,
      policy     TEXT    NOT NULL CHECK(policy IN ('allow','deny','require_approval','allow_always')),
      updated_at TEXT    DEFAULT (datetime('now')),
      PRIMARY KEY (user_id, category)
    );

CREATE TABLE user_auth_providers (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    user_id INTEGER NOT NULL,
    provider_key TEXT NOT NULL,
    provider_user_id TEXT NOT NULL,
    email TEXT,
    metadata_json TEXT DEFAULT '{}',
    last_used_at TEXT,
    created_at TEXT DEFAULT (datetime('now')),
    updated_at TEXT DEFAULT (datetime('now')),
    FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE CASCADE,
    UNIQUE(provider_key, provider_user_id)
  );

CREATE TABLE user_delegations (
      managed_user_id INTEGER PRIMARY KEY REFERENCES users(id) ON DELETE CASCADE,
      manager_user_id INTEGER NOT NULL REFERENCES users(id) ON DELETE CASCADE,
      allowed_permissions_json TEXT NOT NULL DEFAULT '[]',
      invite_id TEXT REFERENCES delegation_invites(id) ON DELETE SET NULL,
      created_at TEXT NOT NULL DEFAULT (datetime('now')),
      CHECK (managed_user_id <> manager_user_id)
    );

CREATE TABLE user_device_pairings (
      id INTEGER PRIMARY KEY AUTOINCREMENT,
      user_id INTEGER NOT NULL REFERENCES users(id) ON DELETE CASCADE,
      code_hash TEXT NOT NULL UNIQUE,
      status TEXT NOT NULL DEFAULT 'pending' CHECK (status IN ('pending', 'used')),
      -- What the phone called itself when it redeemed the code.
      device_label TEXT,
      expires_at TEXT NOT NULL,
      used_at TEXT,
      created_at TEXT NOT NULL DEFAULT (datetime('now'))
    );

CREATE TABLE user_email_tokens (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    user_id INTEGER NOT NULL,
    type TEXT NOT NULL,
    email TEXT NOT NULL,
    token_hash TEXT UNIQUE NOT NULL,
    created_at TEXT DEFAULT (datetime('now')),
    expires_at TEXT NOT NULL,
    consumed_at TEXT,
    FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE CASCADE
  );

CREATE TABLE user_qr_login_challenges (
    id TEXT PRIMARY KEY,
    poll_token_hash TEXT UNIQUE NOT NULL,
    approve_secret_hash TEXT NOT NULL,
    status TEXT DEFAULT 'pending',
    request_user_agent TEXT,
    request_ip_address TEXT,
    request_location_label TEXT,
    request_location_json TEXT DEFAULT '{}',
    request_metadata_json TEXT DEFAULT '{}',
    approved_by_user_id INTEGER,
    approved_session_hash TEXT,
    approved_metadata_json TEXT DEFAULT '{}',
    scanned_metadata_json TEXT DEFAULT '{}',
    expires_at TEXT NOT NULL,
    scanned_at TEXT,
    approved_at TEXT,
    claimed_at TEXT,
    created_at TEXT DEFAULT (datetime('now')),
    FOREIGN KEY (approved_by_user_id) REFERENCES users(id) ON DELETE SET NULL
  );

CREATE TABLE user_recovery_codes (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    user_id INTEGER NOT NULL,
    code_hash TEXT NOT NULL,
    used_at TEXT,
    created_at TEXT DEFAULT (datetime('now')),
    FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE CASCADE
  );

CREATE TABLE user_sessions (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    user_id INTEGER NOT NULL,
    session_hash TEXT UNIQUE NOT NULL,
    ip_address TEXT,
    user_agent TEXT,
    location_label TEXT,
    location_json TEXT DEFAULT '{}',
    created_at TEXT DEFAULT (datetime('now')),
    last_seen_at TEXT DEFAULT (datetime('now')),
    expires_at TEXT,
    revoked_at TEXT,
    FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE CASCADE
  );

CREATE TABLE user_settings (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    user_id INTEGER NOT NULL,
    key TEXT NOT NULL,
    value TEXT,
    FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE CASCADE,
    UNIQUE(user_id, key)
  );

CREATE TABLE user_skill_overrides (
    user_id INTEGER NOT NULL,
    skill_name TEXT NOT NULL,
    enabled INTEGER,
    hidden INTEGER NOT NULL DEFAULT 0,
    updated_at TEXT DEFAULT (datetime('now')),
    PRIMARY KEY (user_id, skill_name),
    FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE CASCADE
  );

CREATE TABLE user_two_factor (
    user_id INTEGER PRIMARY KEY,
    secret TEXT,
    pending_secret TEXT,
    enabled INTEGER DEFAULT 0,
    created_at TEXT DEFAULT (datetime('now')),
    enabled_at TEXT,
    updated_at TEXT DEFAULT (datetime('now')),
    FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE CASCADE
  );

CREATE TABLE user_webauthn_credentials (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    user_id INTEGER NOT NULL,
    credential_id TEXT UNIQUE NOT NULL,
    public_key TEXT NOT NULL,
    counter INTEGER DEFAULT 0,
    rp_id TEXT NOT NULL,
    transports_json TEXT DEFAULT '[]',
    device_type TEXT,
    backed_up INTEGER DEFAULT 0,
    user_verified INTEGER DEFAULT 0,
    label TEXT NOT NULL,
    created_at TEXT DEFAULT (datetime('now')),
    last_used_at TEXT,
    FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE CASCADE
  );

CREATE TABLE users (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    username TEXT UNIQUE NOT NULL,
    email TEXT UNIQUE,
    email_verified_at TEXT,
    password TEXT NOT NULL,
    password_login_enabled INTEGER DEFAULT 1,
    created_at TEXT DEFAULT (datetime('now')),
    last_login TEXT,
    has_completed_onboarding INTEGER DEFAULT 0
  , is_admin INTEGER NOT NULL DEFAULT 0, display_name TEXT, rate_limit_4h INTEGER, rate_limit_weekly INTEGER, allowed_models TEXT);

CREATE TABLE web_shares (
      id TEXT PRIMARY KEY,
      user_id INTEGER NOT NULL REFERENCES users(id) ON DELETE CASCADE,
      agent_id TEXT,
      slug TEXT NOT NULL,
      title TEXT NOT NULL DEFAULT '',
      port INTEGER NOT NULL,
      created_at TEXT NOT NULL DEFAULT (datetime('now')),
      updated_at TEXT NOT NULL DEFAULT (datetime('now')),
      UNIQUE(user_id, slug)
    );

CREATE TABLE workspace_code_index (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    user_id INTEGER NOT NULL,
    path TEXT NOT NULL,
    symbol TEXT,
    symbol_type TEXT,
    start_line INTEGER,
    end_line INTEGER,
    content TEXT NOT NULL,
    content_hash TEXT NOT NULL,
    embedding TEXT,
    updated_at TEXT DEFAULT (datetime('now')),
    FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE CASCADE,
    UNIQUE(user_id, path, symbol, start_line)
  );

