CREATE TRIGGER cleanup_expired_oauth_states
  AFTER INSERT ON integration_oauth_states BEGIN
    DELETE FROM integration_oauth_states
    WHERE datetime(expires_at) <= datetime('now');
  END;

CREATE TRIGGER conversation_history_fts_ad AFTER DELETE ON conversation_history BEGIN
      DELETE FROM conversation_history_fts WHERE rowid = old.id;
    END;

CREATE TRIGGER conversation_history_fts_ai AFTER INSERT ON conversation_history BEGIN
      INSERT INTO conversation_history_fts(rowid, content, role, user_id, agent_id, agent_run_id)
      VALUES (new.id, COALESCE(new.content, ''), new.role, new.user_id, COALESCE(new.agent_id, ''), COALESCE(new.agent_run_id, ''));
    END;

CREATE TRIGGER conversation_history_fts_au AFTER UPDATE ON conversation_history BEGIN
      DELETE FROM conversation_history_fts WHERE rowid = old.id;
      INSERT INTO conversation_history_fts(rowid, content, role, user_id, agent_id, agent_run_id)
      VALUES (new.id, COALESCE(new.content, ''), new.role, new.user_id, COALESCE(new.agent_id, ''), COALESCE(new.agent_run_id, ''));
    END;

CREATE TRIGGER messages_fts_ad AFTER DELETE ON messages BEGIN
      DELETE FROM messages_fts WHERE rowid = old.id;
    END;

CREATE TRIGGER messages_fts_ai AFTER INSERT ON messages BEGIN
      INSERT INTO messages_fts(rowid, content, role, user_id, agent_id, run_id, platform, platform_chat_id)
      VALUES (new.id, COALESCE(new.content, ''), new.role, new.user_id, COALESCE(new.agent_id, ''), COALESCE(new.run_id, ''), COALESCE(new.platform, ''), COALESCE(new.platform_chat_id, ''));
    END;

CREATE TRIGGER messages_fts_au AFTER UPDATE ON messages BEGIN
      DELETE FROM messages_fts WHERE rowid = old.id;
      INSERT INTO messages_fts(rowid, content, role, user_id, agent_id, run_id, platform, platform_chat_id)
      VALUES (new.id, COALESCE(new.content, ''), new.role, new.user_id, COALESCE(new.agent_id, ''), COALESCE(new.run_id, ''), COALESCE(new.platform, ''), COALESCE(new.platform_chat_id, ''));
    END;

CREATE TRIGGER users_first_active_account_is_admin
    AFTER INSERT ON users
    WHEN NOT (NEW.email_verified_at IS NULL AND trim(COALESCE(NEW.email, '')) != '') AND (SELECT COUNT(*) FROM users WHERE NOT (email_verified_at IS NULL AND trim(COALESCE(email, '')) != '')) = 1
    BEGIN
      UPDATE users SET is_admin = 1 WHERE id = NEW.id;
    END;

CREATE TRIGGER users_first_confirmed_account_is_admin
    AFTER UPDATE OF email_verified_at ON users
    WHEN OLD.email_verified_at IS NULL AND NEW.email_verified_at IS NOT NULL
      AND (SELECT COUNT(*) FROM users WHERE NOT (email_verified_at IS NULL AND trim(COALESCE(email, '')) != '')) = 1
    BEGIN
      UPDATE users SET is_admin = 1 WHERE id = NEW.id;
    END;
